  (forall i, fb + 32 <= i < fb + 2040 -> L5.outside Wc i) -> (forall a, 65536 <= a < 7036928 -> L5.outside Wc a) ->
  (forall B m, In (B, m) LB1 -> forall i, B <= i < B + m -> L5.outside Wc i) ->
  mrun_pre M1 fb s1 st str sm1 e1 n -> mrun_pre M4 fb s1 st str sm1 e1 n.
