(* [comment removed for export] *)
Lemma mk_call_read M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 ev ecat (fx1 : FPState) R1 (ra off kk v : Z) :
  PQRAa.src_read_spec L ar HI -> 5 <= h ->
  m_mem M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 ev ecat ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 (fb + 592 + 24) -> getr R1 (reg 11) = Z_to_bv 64 (F + off) -> getr R1 (reg 12) = Z_to_bv 64 kk ->
  32 <= off -> off + kk <= B - 8 -> off mod 8 = 0 -> ((kk = 8 /\ v = 0) \/ (1 <= kk <= 7 /\ v = kk)) ->
  L5.u8_at RSEGS M1 (F / 8 + off / 8 + 2147450880) v ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 src3 sm3 d,
      regs_preserved R1 R2 -> getr R2 (reg 10) = Z_to_bv 64 d -> 0 <= d <= kk ->
      PM.unread src3 sm3 = PM.unread (PQMA.p_src s1) sm1 - d ->
      (1 <= PM.sr_rem (PQMA.p_src s1) -> 1 <= d) -> (d = 0 -> PM.sr_rem src3 = 0 /\ PM.sm_st sm3 = 2) ->
      L5.defined M3 (F + off) d -> PM.sr_qc src3 = PM.sr_qc (PQMA.p_src s1) ->
      m_mem M3 model3 LK3 Aw3 (PQMA.with_src s1 src3) sa1 sm3 e1 cr1 ev ecat ->
      (forall a, spc <= a < sp -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 (pa_src_read AD) M1 model1) K.
