Section Enter.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r fb cat n : Z) (s : PQMA.mpst) (sa : PQMA.ast) (str : PM.vstr) (sm : PM.strm) (e : bool) (h : Z).
Hypothesis HH : ri_inv HI (mown s sa ++ LBX) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r h.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM h FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis FOK : PQRA.frame_okM FF fb.
Hypothesis RPRE : mrun_pre M fb s sa str sm e n.
Hypothesis INCS : incl (PM.vs_own str) LBX.
Hypothesis EC0 : PMSPA.ec_at RSEGS M (fb + 1232) 0 cat.
Hypothesis Hh : 1 <= h <= 16.

Lemma mk_enter (spc olo ohi : Z) (ocell : Z -> Prop) (own : mem -> Prop) (k : Z) (fx fx1 : FPState) R1 (pc0 rr : Z) (M1v : mem) :
  In k [0; 1; 2; 3; 4; 5] ->
  sp - 2048 <= spc -> spc mod 16 = 0 -> spc <= olo -> olo <= ohi -> ohi <= sp ->
  (forall a, ocell a -> olo <= a < ohi) ->
  (forall Ma Mb, own Ma -> (forall a, ocell a -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) -> own Mb) ->
  msteps RSEGS (st fx R pc0 (mrestrict (ahid Aw model) M)) (st fx1 R1 (PMA.SM_PC k) M1v) ->
  mem_grows (mrestrict (ahid Aw model) M) M1v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ (spc <= a < sp) -> M1v (Z_to_bv 64 a) = mrestrict (ahid Aw model) M (Z_to_bv 64 a)) ->
  (forall M1 : mem, mrestrict (ahid Aw model) M1 = M1v -> (forall a n0, spc <= a -> a + n0 <= sp -> avis (ahid Aw model) a n0) -> own M1) ->
  getr R1 (reg 2) = Z_to_bv 64 spc -> getr R1 (reg 4) = getr R (reg 4) -> getr R1 (reg 1) = Z_to_bv 64 rr -> rr mod 2 = 0 -> 0 <= rr < 2 ^ 64 ->
  (forall (R2 : bvmap 5 word) (M2 : mem) (model2 : Model) (F fl : Z) (LK2 : list fframe),
      PMAUK.gctx L ar HI LBX FF LK Aw sp (PMSPA.pm_scr h) spc olo ohi ocell own F fl k LK2 M2 model2 cr (mown s sa) ->
      (forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar (mown s sa ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes k <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes k / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a)) ->
      m_mem M model LBX FF LK Aw sp fb n s sa str sm e h spc own k F M2 model2 LK2 Aw s sa sm e cr 0 cat ->
      getr R2 (reg 10) = Z_to_bv 64 F -> regs_preserved R1 R2 ->
      L5KA.zeros_at (mrestrict (ahid Aw model2) M2) (F / 8 + SB) (ff_bytes k / 8) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R2 rr M2 model2) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R pc0 M model) K.
