(* [comment removed for export] *)
(* [comment removed for export] *)
Section FnR.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r fb cat n : Z) (s : PQMA.mpst) (sa : PQMA.ast) (str : PM.vstr) (sm : PM.strm) (e : bool) (h : Z).
Hypothesis HH : ri_inv HI (mown s sa ++ LBX) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r h.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM h FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis FOK : PQRA.frame_okM FF fb.
Hypothesis RPRE : mrun_pre M fb s sa str sm e n.
Hypothesis INCS : incl (PM.vs_own str) LBX.
Hypothesis EC0 : PMSPA.ec_at RSEGS M (fb + 1232) 0 cat.
Hypothesis Hh : 1 <= h <= 16.
(* [comment removed for export] *)
Variables (FR : Z) (ocell : Z -> Prop) (own : mem -> Prop).
Hypothesis HFR : 16 <= FR <= 2048 /\ FR mod 16 = 0.
Hypothesis GOCR : forall a, ocell a -> sp - FR <= a < sp.
Hypothesis GOWN : forall M1 M1' : mem, own M1 -> (forall a, ocell a -> M1' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> own M1'.
Local Notation spc := (sp - FR).
Local Notation SCR := (PMSPA.pm_scr h).
Local Notation WR := (W_mrun fb).

(* [comment removed for export] *)
Definition binvG (own' : mem -> Prop) (BX : list (Z * Z)) (M1 : mem) (model1 : Model) (LK1 : list fframe) (cr1 : credit) (Aw1 : list (Z * Z)) : Prop :=
  ri_inv HI (BX ++ LBX) FF LK1 cr1 Aw1 M1 (vml_of model1) /\ L5CA.amodel_ok Aw1 model1 /\ model_rt model model1 /\ incl Aw Aw1 /\ incl LK1 LK /\
  L5CA.astk ar M1 sp SCR /\ ek L ar LBX FF sp SCR WR M M1 /\ dk L ar LBX FF sp SCR M M1 /\ own' M1.
