(* [comment removed for export] *)
Lemma mk_call_getsize M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 ecat (fx1 : FPState) R1 (ra d t : Z) :
  PQRAa.get_size_spec L ar HI -> 6 <= h -> 0 <= d <= 1 ->
  m_memR M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 0 ecat ->
  PQMA.cpl s1 sa1 -> PQMA.acct n s1 sa1 sm1 -> PQRA.minv_d d s1 ->
  PMSP.credit_le (PMSPA.scA L (PM.credit_add (PQMA.pot_run (PMSPA.HV L ar) s1 sa1) PQMA.TSRES)) cr1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 (fb + 592) -> getr R1 (reg 11) = Z_to_bv 64 t -> PQRA.gs_type t -> getr R1 (reg 12) = Z_to_bv 64 (fb + 1232) ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 s3 sa3 sm3 e3 cr3 ev3 ecat3,
      regs_preserved R1 R2 ->
      m_memR M3 model3 LK3 Aw3 s3 sa3 sm3 e3 cr3 ev3 ecat3 ->
      PQMA.cpl s3 sa3 -> PQMA.acct n s3 sa3 sm3 ->
      ((exists v, 1 <= v <= 64 /\ ev3 = v /\ ecat3 = pa_errcat_obj AD /\ PQMA.p_more s3 = 0 /\ e3 = true)
       \/ (ev3 = 0 /\ ecat3 = ecat /\ PQRA.minv_d d s3 /\ PQRA.mprog_len R2 M3 s1 s3 sa1 sa3 sm1 sm3 /\ PQRA.room_keep s1 s3 sm1 sm3)) ->
      PMSP.credit_keep cr1 cr3 (PMSPA.scA L (PQMA.pot_run (PMSPA.HV L ar) s1 sa1)) (PMSPA.scA L (PQMA.pot_run (PMSPA.HV L ar) s3 sa3)) ->
      (forall a, spc <= a < sp -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 (qa_get_size AQ) M1 model1) K.
