(* [comment removed for export] *)
Lemma mk_call_slot M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 ev ecat (fx1 : FPState) R1 (pc ra : Z)
      (args : bvmap 5 word -> mem -> list fframe -> list (Z * Z) -> Z -> Prop) (pre : bvmap 5 word -> mem -> PQMA.ast -> Prop)
      (step : bvmap 5 word -> mem -> PQMA.ast -> PQMA.ast -> Prop) :
  PQVA.vis_spec RSEGS AD AQ L ar HI pc args pre step -> 4 <= h ->
  m_memR M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 ev ecat ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 (fb + 992) ->
  args R1 M1 FF (PQMA.mparser_own s1 ++ LBX) (fb + 992) -> pre R1 M1 sa1 ->
  PMSP.credit_le (PMSPA.scA L (PQMA.pot_adaptor (PMSPA.HV L ar) sa1)) cr1 ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 sa3 cr3,
      regs_preserved R1 R2 ->
      m_memR M3 model3 LK3 Aw3 s1 sa3 sm1 e1 cr3 ev ecat ->
      PQMA.adaptor_ok sa3 -> step R1 M1 sa1 sa3 ->
      PMSP.credit_keep cr1 cr3 (PMSPA.scA L (PQMA.pot_adaptor (PMSPA.HV L ar) sa1)) (PMSPA.scA L (PQMA.pot_adaptor (PMSPA.HV L ar) sa3)) ->
      (forall a, spc <= a < sp -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
