(* [comment removed for export] *)
Lemma mk_call_push M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 ev ecat (fx1 : FPState) R1 (pcp ra off1 off2 m len : Z) :
  PQSAXQ.push_cont_spec RSEGS AD L ar HI pcp -> 1 <= h ->
  m_memR M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 ev ecat ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 (fb + 968) -> getr R1 (reg 11) = Z_to_bv 64 (spc + off1) -> getr R1 (reg 12) = Z_to_bv 64 (spc + off2) ->
  0 <= off1 -> off1 + 4 <= FR -> off1 mod 4 = 0 -> 0 <= off2 -> off2 + 8 <= FR -> off2 mod 8 = 0 ->
  L5.u32_at RSEGS M1 (spc + off1) m -> 0 <= m < 2 ^ 31 -> L5.u64_at RSEGS M1 (spc + off2) len -> 0 <= len < 2 ^ 64 ->
  (Z.of_nat (length (PQMA.p_stk s1)) = 2 ^ PQMA.p_sk s1 -> PQMA.p_sk s1 <= 10 /\ acredit_ok L cr1 (PQMA.PSZ * 2 ^ (PQMA.p_sk s1 + 1))) ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 b' k' cr3,
      regs_preserved R1 R2 ->
      m_memR M3 model3 LK3 Aw3 (PQAKOA.set_vec s1 b' k' (PQMA.p_stk s1 ++ [PQMA.MS m len 0])) sa1 sm1 e1 cr3 ev ecat ->
