Lemma obj_pf_u LB FF LK cr Aw (M : mem) model o n :
  ri_inv HI LB FF LK cr Aw M (vml_of model) -> PMSPA.aobjA FF o n -> 0 < n ->
  (7036928 <= o /\ o + n <= ahl_ceil ar /\ o + n <= 2 ^ 47 /\ (2147446784 + 17592186048512 <= o \/ o + n <= 2147446784))
  /\ avis (ahid Aw model) o n /\ L5.defined M o n
