Lemma adaptor_keepE LB1 FFx spx scr Wc (M1 M4 : mem) oa ov st :
  (forall f, In f FFx -> 0 <= ff_addr f /\ ff_addr f + ff_bytes (ff_class f) <= 2 ^ 47) -> (forall b, In b LB1 -> 0 <= fst b /\ fst b + snd b <= 2 ^ 47) ->
  ek L ar LB1 FFx spx scr Wc M1 M4 -> PMKA.wapp Wc -> incl (PQMA.aown st) LB1 -> PMSPA.aobjA FFx oa PQMA.ASIZE ->
  (forall i, oa <= i < oa + PQMA.ASIZE -> L5.outside Wc i) ->
  (forall B m, In (B, m) (PQMA.aown st) -> forall i, B <= i < B + m -> L5.outside Wc i) ->
  adaptor_at M1 oa ov st -> adaptor_at M4 oa ov st.
