Section Frame.
Variables (spc olo ohi : Z) (ocell : Z -> Prop) (own : mem -> Prop) (k F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PMAUK.gctx L ar HI LBX FF LK Aw sp (PMSPA.pm_scr h) spc olo ohi ocell own F fl k LK2 M2 model2 cr BX0.
Hypothesis APART : forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar (BX0 ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes k <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes k / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Hypothesis HSPC : sp - 2048 <= spc /\ spc mod 16 = 0.
Local Notation B := (ff_bytes k).
Local Notation FF' := ((F, k, spc + 32) :: FF).

Definition g_mem (BX1 : list (Z * Z)) (M1 : mem) (model1 : Model) (LK1 : list fframe) (Aw1 : list (Z * Z)) (cr1 : credit) : Prop :=
  PMAUK.binv L ar HI M model LBX FF LK Aw sp SCR spc own F k W BX1 M1 model1 LK1 cr1 Aw1.

(* [comment removed for export] *)
Lemma g_apart1 BX1 M1 model1 LK1 Aw1 cr1 a sp0 scr0 :
  g_mem BX1 M1 model1 LK1 Aw1 cr1 -> aclient L ar (BX1 ++ LBX) FF sp0 scr0 a ->
  ~ (F <= a < F + B) /\ ~ (F / 8 + SB <= a < F / 8 + SB + B / 8) /\ a <> fl.
