Section ObjL.
Variables M M' : mem.
(* [comment removed for export] *)
Lemma lvec_set_lastA v b k lv c c' :
  lvec_at M v b k (lv ++ [c]) ->
  0 <= v -> v + 24 <= 2 ^ 64 -> 0 <= b -> b + 24 * 2 ^ k <= 2 ^ 64 ->
  L5C.agree_on M M' v 24 -> L5C.agree_on M M' b (24 * Z.of_nat (length lv)) -> PMFA.agsh M M' b (24 * 2 ^ k) -> L5.defined M' b (24 * 2 ^ k) ->
  PQMA.alvl_at RSEGS M' (b + 24 * Z.of_nat (length lv)) c' ->
