(* [comment removed for export] *)
Lemma cle_sel3 (bl : Z) (p1 p2 p3 q cr : credit) : 0 <= bl -> 0 <= fst p1 -> 0 <= snd p1 -> 0 <= fst p2 -> 0 <= snd p2 -> 0 <= fst p3 -> 0 <= snd p3 ->
  q = p1 \/ q = p2 \/ q = p3 ->
  fst p1 + (fst p2 + fst p3) <= fst cr /\ bl * (snd p1 + (snd p2 + snd p3)) <= snd cr -> fst q <= fst cr /\ bl * snd q <= snd cr.
Proof.
