(* [comment removed for export] *)
Lemma s_oa M1 model1 LK1 Aw1 st1 cr1 :
  a_mem M1 model1 LK1 Aw1 st1 cr1 ->
  let MV := mrestrict (ahid Aw1 model1) M1 in
  (7036928 <= oa /\ oa <= 140737488355232 /\ (2147446784 + 17592186048512 <= oa \/ oa + 96 <= 2147446784) /\ oa + 96 <= ahl_ceil ar /\ oa + 96 <= spc)
  /\ (forall c, 0 <= c < 96 -> L5KA.zeros_at MV ((oa + c) / 8 + 2147450880) 1)
  /\ L5.u64_at RSEGS MV (oa + 16) ov
  /\ (7036928 <= ov /\ ov <= 140737488355320 /\ (2147446784 + 17592186048512 <= ov \/ ov + 8 <= 2147446784) /\ ov + 8 <= spc
      /\ L5KA.zeros_at MV (ov / 8 + 2147450880) 1 /\ L5.u64_at RSEGS MV ov 1381384)
  /\ L5.img_clear MV 65536 1409024
  /\ (forall slot, 0 <= slot <= 272 -> slot mod 8 = 0 -> L5KA.zeros_at MV ((1381384 + slot) / 8 + 2147450880) 1)
  /\ ((oa + 96 <= F \/ F + B <= oa) /\ (ov + 8 <= F \/ F + B <= ov)
      /\ (forall c, 0 <= c < 96 -> (oa + c) / 8 + 2147450880 + 1 <= F / 8 + 2147450880 \/ F / 8 + 2147450880 + B / 8 <= (oa + c) / 8 + 2147450880)
      /\ (ov / 8 + 2147450880 + 1 <= F / 8 + 2147450880 \/ F / 8 + 2147450880 + B / 8 <= ov / 8 + 2147450880))
