(* [comment removed for export] *)
Lemma s_blk M1 model1 LK1 Aw1 st1 cr1 q m :
  a_mem M1 model1 LK1 Aw1 st1 cr1 -> In (q, m) (PQMA.aown st1) ->
  let MV := mrestrict (ahid Aw1 model1) M1 in
  (4096 <= q /\ q mod 16 = 0 /\ 0 < m /\ q + m <= ahl_ceil ar /\ q + m <= 2 ^ 47 /\ (q + m <= 2147446784 \/ 2147446784 + 17592186048512 <= q) /\ (q + m <= 65536 \/ 7036928 <= q))
  /\ (q + m <= oa \/ oa + 96 <= q) /\ (q + m <= ov \/ ov + 8 <= q) /\ (q + m <= F \/ F + B <= q) /\ q + m <= spc
  /\ avis (ahid Aw1 model1) q m
  /\ (forall x, q <= x -> x + 8 <= q + m -> accA M1 x 8 ->
        L5KA.zeros_at MV (x / 8 + 2147450880) 1
