Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Let LYa := PMA.ly_as0 L C LY.

Section Gen.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r h : Z) (BX0 : list (Z * Z)) (W : list L5.range).
Hypothesis HH : ri_inv HI (BX0 ++ LBX) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r h.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM h FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis Hh : 1 <= h <= 16.
Hypothesis WAPP : PMKA.wapp W.
Local Notation SCR := (PMSPA.pm_scr h).

Section Frame.
Variables (spc olo ohi : Z) (ocell : Z -> Prop) (own : mem -> Prop) (k F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PMAUK.gctx L ar HI LBX FF LK Aw sp SCR spc olo ohi ocell own F fl k LK2 M2 model2 cr BX0.
Hypothesis APART : forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar (BX0 ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes k <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes k / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Hypothesis HSPC : sp - 2048 <= spc /\ spc mod 16 = 0.
Local Notation B := (ff_bytes k).
Local Notation FF' := ((F, k, spc + 32) :: FF).
Local Notation g_mem := (PQAKR3.g_mem L ar HI M model LBX FF LK Aw sp h W spc own k F).

(* [comment removed for export] *)
Lemma g_stksh BX1 M1 model1 LK1 Aw1 cr1 lo g :
  g_mem BX1 M1 model1 LK1 Aw1 cr1 -> sp - SCR <= lo -> lo + 8 * g <= sp -> lo mod 8 = 0 -> 0 <= g ->
