Lemma iosb_revptr (M1 M2 : word -> option byte) o vp vp' rdb st :
  PM.iosb_at RSEGS PMA.AD PMSPA.accA M1 o vp rdb st -> L5.u64_at RSEGS M2 o vp' ->
