Lemma bparser_at_agreeA op ois s : 0 <= op -> op + PNM.PSIZE <= 2 ^ 64 -> PMFA.agA M1 M2 op PNM.PSIZE ->
  PMFA.agA M1 M2 (PM.sr_qc (PNM.b_src s)) PM.CHUNK -> 0 <= PM.sr_qc (PNM.b_src s) -> PM.sr_qc (PNM.b_src s) + PM.CHUNK <= 2 ^ 64 ->
