Lemma pre_after LB1 FFx spx scr Wc (M1 M4 : mem) fb s1 s4 st str sm1 sm4 e1 e4 n :
  (forall f, In f FFx -> 0 <= ff_addr f /\ ff_addr f + ff_bytes (ff_class f) <= 2 ^ 47) -> (forall b, In b LB1 -> 0 <= fst b /\ fst b + snd b <= 2 ^ 47) ->
  ek L ar LB1 FFx spx scr Wc M1 M4 -> PMKA.wapp Wc -> PQRA.frame_okM FFx fb -> incl (PQMA.aown st) LB1 ->
  (forall i, (fb + 496 <= i < fb + 504 \/ fb + 992 <= i < fb + 1096) -> L5.outside Wc i) ->
  (forall B m, In (B, m) (PQMA.aown st) -> forall i, B <= i < B + m -> L5.outside Wc i) ->
  mrun_pre M1 fb s1 st str sm1 e1 n ->
  mparser_at M4 (fb + 592) (fb + 96) s4 -> PM.iss_at RSEGS AD accA M4 (fb + 96) str sm4 -> PQMA.mgrow_ok s4 ->
  PMSTA.base_okA RSEGS AD M4 -> PQSTA.err_okA RSEGS AD AAD AQ M4 e4 -> PQMA.cpl s4 st -> PQMA.acct n s4 st sm4 ->
  mrun_pre M4 fb s4 st str sm4 e4 n.
