(* [comment removed for export] *)
Section Fn.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r fb cat n : Z) (s : PQMA.mpst) (sa : PQMA.ast) (str : PM.vstr) (sm : PM.strm) (e : bool) (h : Z).
Hypothesis HH : ri_inv HI0 (mown s sa ++ LBX) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r h.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM h FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis FOK : PQRA.frame_okM FF fb.
Hypothesis RPRE : mrun_pre M fb s sa str sm e n.
Hypothesis INCS : incl (PM.vs_own str) LBX.
Hypothesis Hh : 1 <= h <= 16.
(* [comment removed for export] *)
Variables (spc olo ohi : Z) (ocell : Z -> Prop) (own : mem -> Prop) (k F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PQAKUF.gctx L ar HIk D0 LBX FF LK Aw sp (PMSPA.pm_scr h) spc olo ohi ocell own F fl k LK2 M2 model2 cr (mown s sa).
Hypothesis APART : forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar (mown s sa ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes k <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes k / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Hypothesis HSPC : sp - 2048 <= spc /\ spc mod 16 = 0.
Local Notation B := (ff_bytes k).
Local Notation FF' := ((F, k, spc + 32) :: FF).
Local Notation SCR := (PMSPA.pm_scr h).
Local Notation WR := (W_mrun fb).
Local Notation LB0 := (mown s sa ++ LBX).

(* [comment removed for export] *)
Definition m_mem (M1 : mem) (model1 : Model) (LK1 : list fframe) (Aw1 : list (Z * Z)) (s1 : PQMA.mpst) (sa1 : PQMA.ast) (sm1 : PM.strm) (e1 : bool)
           (cr1 : credit) (ev ecat : Z) : Prop :=
  PQAKUF.binv L ar HIk D1 M model LBX FF LK Aw sp SCR spc own F k WR (mown s1 sa1) M1 model1 LK1 cr1 Aw1
  /\ mrun_pre M1 fb s1 sa1 str sm1 e1 n
  /\ PMSPA.ec_at RSEGS M1 (fb + 1232) ev ecat
  /\ PMSP.src_step (PQMA.p_src s) (PQMA.p_src s1) sm sm1 /\ (e = true -> e1 = true)
  /\ mown s1 sa1 = mown s sa.

(* [comment removed for export] *)
Lemma ctx_facts :
  (7036928 <= fb /\ fb + 2048 <= ahl_ceil ar /\ fb mod 2048 = 0 /\ (2147446784 + 17592186048512 <= fb \/ fb + 2048 <= 2147446784))
  /\ (ahl_ceil ar + 4096 + SCR <= sp /\ sp <= ar_sptop ar /\ 140735340871680 <= ar_sptop ar <= 2 ^ 47 /\ sp mod 16 = 0)
  /\ (exists rs, In (fb, 5, rs) FF).
