Lemma mk_fin M5 model5 LK5 Aw5 s5 sa5 sm5 e5 cr5 ev ecat (fx5 fx9 : FPState) R5 R9 (pc5 : Z) (M9v : mem) (prog : PQRA.mprog) (d : Z) :
  m_mem M5 model5 LK5 Aw5 s5 sa5 sm5 e5 cr5 ev ecat ->
  msteps RSEGS (st fx5 R5 pc5 (mrestrict (ahid Aw5 model5) M5)) (st fx9 R9 r M9v) ->
  mem_grows (mrestrict (ahid Aw5 model5) M5) M9v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ PQAKUF.WretX F fl k (fun _ => False) a -> M9v (Z_to_bv 64 a) = mrestrict (ahid Aw5 model5) M5 (Z_to_bv 64 a)) ->
  L5.u8_at RSEGS M9v fl 0 ->
  regs_preserved R R9 ->
  ( (exists v, 1 <= v <= 64 /\ ev = v /\ ecat = pa_errcat_obj AD /\ PQMA.p_more s5 = 0 /\ e5 = true)
    \/ (ev = 0 /\ ecat = cat /\ PQRA.minv_d d s5 /\ (forall Mf, prog R9 Mf s s5 sa sa5 sm sm5) /\ PQRA.room_keep s s5 sm sm5) ) ->
  PMSP.credit_keep cr cr5 (PMSPA.scA L (PQMA.pot_run (PMSPA.HV L ar) s sa)) (PMSPA.scA L (PQMA.pot_run (PMSPA.HV L ar) s5 sa5)) ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (s' : PQMA.mpst) (st' : PQMA.ast)
          (sm' : PM.strm) (e' : bool) (cr' : credit),
      regs_preserved R R' ->
      PQRA.mrun_post_d RSEGS AD AQ AAD d prog R' M' fb s s' sa st' str sm sm' e e' cat n ->
      L5CA.ahpres L ar LBX FF sp SCR (W_mrun fb) M M' ->
      PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_run (PMSPA.HV L ar) s sa)) (PMSPA.scA L (PQMA.pot_run (PMSPA.HV L ar) s' st')) ->
      model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (mown s' st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 pc5 M5 model5) K.
Proof using All.
